 // this variable will hold our shader object
 let theShader;
 // this variable will hold our createGraphics layer
 let shaderTexture;

 let theta = 0;

 let x;
 let y;
 let outsideRadius = 200;
 let insideRadius = 100;

 let myFont;

 function preload(){
   // load the shader
   theShader = loadShader('https://openprocessing.org/sketch/1373308/files/texture.vert','texture.frag');
	 mp3 = loadSound("https://openprocessing.org/sketch/1373308/files/a51.mp3");
	 myFont = loadFont('https://openprocessing.org/sketch/1373308/files/BlockyLettersHollow.ttf');
 }

 function setup() {
   // shaders require WEBGL mode to work
   createCanvas(888, 888, WEBGL);
   noStroke();
	 cursor(CROSS);

	 textFont(myFont);
	 textSize(44);
	 textAlign(CENTER);

	 mp3.loop();

   // initialize the createGraphics layers
   shaderTexture = createGraphics(710, 400, WEBGL);

   // turn off the createGraphics layers stroke
   shaderTexture.noStroke();

    x = -50;
    y = 0;
 }

 function draw() {

   // instead of just setting the active shader we are passing it to the createGraphics layer
   shaderTexture.shader(theShader);

   // here we're using setUniform() to send our uniform values to the shader
   theShader.setUniform("resolution", [width, height]);
   theShader.setUniform("time", millis() / 1000.0);
   theShader.setUniform("mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);

   // passing the shaderTexture layer geometry to render on
   shaderTexture.rect(0,0,width,height);

   background('orange');
	 lights();
	 ambientLight(222);

	 stroke(2)
	 fill(2)
	 strokeWeight(2);
	 text('remote control',0,-height/2+70);

   // pass the shader as a texture
   texture(shaderTexture);




  scale(0.5);
	rotateY(radians(-frameCount*.5));
	rotateY(radians((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))));
	v = radians(frameCount);
  for (var u=0;u<540;u++){
  x = u*(cos(4*u/4+sin(v)*cos(u)));
  y = u*(sin(4*u)/4+sin(u));
  z = cos(u);
  strokeWeight(random(2,3));
  stroke(2);
  ellipsoid(x*.8,y,z*222);}



 }

